INSERT INTO `GAC_hardloopschema` VALUES (1,1,'2025-01-14','5 x 2 min hardlopen, 2 min wandelen','Skippings, hielen-billen, versnellingen (4x 50m)','2025-01-18','20+10 min rustige duurloop','Knieheffen, laddersprongen','20 min rustige duurloop','Rustig lopen, korte versnellingen','Fase 1: Basisconditie (12 jan - 23 feb, 5 km)','','2025-01-13 19:53:02','2025-01-16 15:45:55','virgilsmit@gmail.com','dannyvdw@me.com'),(2,2,'2025-01-21','6 x 2 min hardlopen, 2 min wandelen','Huppelpas, zijwaartse sprongen','2025-01-25','30 min rustige duurloop','Dynamische lunges, skipping','25 min tempo duurloop','Lichte looptechniek oefeningen','Fase 1: Basisconditie (12 jan - 23 feb, 5 km)','','2025-01-13 19:53:02','2025-01-21 16:57:26','virgilsmit@gmail.com','dannyvdw@me.com'),(3,3,'2025-01-28','Fartlek: 2 min snel, 1 min rustig, 7x','Romprotaties, skips met hoge knieën','2025-02-01','35 min rustige duurloop','Knieheffen, huppelpas','30 min rustige duurloop','Dynamische rek- en strekoefeningen','Fase 1: Basisconditie (12 jan - 23 feb, 5 km)','','2025-01-13 19:53:02','2025-02-01 18:38:16','virgilsmit@gmail.com','dannyvdw@me.com'),(4,4,'2025-02-04','3 x 4 min hardlopen, 2 min wandelen','Dynamische stretches, versnellingen (6x 20m)','2025-02-08','40 min rustige duurloop (2 blokken: 25+15 min)','Laddersprongen, zijwaartse shuffles','30 min rustige duurloop','Lichte rustige loop, met afwisselend versnellen','Fase 1: Basisconditie (12 jan - 23 feb, 5 km)','','2025-01-13 19:53:02','2025-02-04 16:20:17','dannyvdw@me.com','dannyvdw@me.com'),(5,5,'2025-02-11','5 x 3 min hardlopen, 2 min wandelen','Korte sprintjes, skipping','2025-02-15','30 min rustige duurloop','Dynamische stretches, skipping','20 min rustig lopen','Flexibiliteitsoefeningen','Fase 1: Basisconditie (12 jan - 23 feb, 5 km)','','2025-01-13 19:53:02','2025-02-11 20:45:11','virgilsmit@gmail.com','dannyvdw@me.com'),(6,6,'2025-02-18','2 x 4 min hardlopen, 2 min wandelen','Versnellingen (wedstrijdvoorbereiding)','2025-02-22','5 km wedstrijd (10 min in- en uitlopen)','Geen (wedstrijdherstel)','Geen (herstel na wedstrijd)','Rust en herstel na wedstrijd','Fase 1: Basisconditie (12 jan - 23 feb, 5 km)','23-feb-25','2025-01-13 19:53:02','2025-02-18 16:37:01','virgilsmit@gmail.com','dannyvdw@me.com'),(7,7,'2025-02-25','4 x 6 min hardlopen, 2 min wandelen','Skippings, versnellingen (8x 30m)','2025-03-01','45 min rustige duurloop','Knieheffen, laddersprongen','30 min rustige duurloop','Korte versnellingen, lichte oefeningen','Fase 2: Snelheid opbouwen (24 feb - 16 mrt, 10 km)','','2025-01-13 19:53:02','2025-01-13 19:53:02',NULL,NULL),(8,8,'2025-03-04','6 x 3 min hardlopen, 1 min rust','Huppelpas, skipping','2025-03-08','50 min rustige duurloop','Skipping, dynamische lunges','35 min tempo duurloop','Knieheffen, snelheidsoefeningen','Fase 2: Snelheid opbouwen (24 feb - 16 mrt, 10 km)','','2025-01-13 19:53:02','2025-03-01 11:22:59','dannyvdw@me.com','virgilsmit@gmail.com'),(9,9,'2025-03-11','Fartlek: 4 min snel, 2 min rustig, 6x','Knieheffen, romprotaties','2025-03-15','55 min rustige duurloop (bos)','Skipping, laddersprongen','30 min rustige duurloop','Dynamische stretching','Fase 2: Snelheid opbouwen (24 feb - 16 mrt, 10 km)','','2025-01-13 19:53:02','2025-03-10 08:14:05','virgilsmit@gmail.com','dannyvdw@me.com'),(10,10,'2025-03-18','3 x 5 min hardlopen, 1 min rust','Versnellingen (wedstrijdvoorbereiding)','2025-03-22','10 km wedstrijd (10 min in- en uitlopen)','Geen (wedstrijdherstel)','Geen (herstel na wedstrijd)','Rust na wedstrijd, lichte oefeningen','Fase 2: Snelheid opbouwen (24 feb - 16 mrt, 10 km)','16-mrt-25','2025-01-13 19:53:02','2025-03-17 13:24:53','dannyvdw@me.com','dannyvdw@me.com'),(11,11,'2025-03-25','3 x 8 min hardlopen, 2 min wandelen','\nLopen met gefixeerde armen (3x15m)\n\n\n1.	Handen aan de oren\n2.	Handen gekruist op borst\n3.	Handen op de rug\n4.	Knieheffen met armen strekken vooruit\n\n5.	Kruispas met handen gekruist op borst en daarna omkeren en in dezelfde richting (15 meter 2x)\n	\n6.	Skippen met armen stijf langs lichaam\n7.	Skippen met versnelling, stijve armen.\n8.	Skippen met versnelling met sterke arminzet (30 meter 3x)\n\n','2025-03-29','4 x 4min - 1,5min herstel interval en 6 minuten vaartspel','•	Skippen 3x \n•	Skipping-hielaanslag versnellen 3x \n•	Gestrekte benenloop 3x \n•	Lopen met gefixeerde armen 2x nek, 2x borst, 2x \n','30 min rustige duurloop','Flexibiliteit en mobiliteitsoefeningen','Fase 3: Duur en snelheid verfijnen (17 mrt - 13 apr, 10 km)','','2025-01-13 19:53:02','2025-03-27 11:29:01','virgilsmit@gmail.com','dannyvdw@me.com'),(12,12,'2025-04-01','•	6  minuten snel  tempo (75-85% van max)\n•	1 minuut rustig Actieve herstelfase met rustig joggen of stevig wandelen.\n•	4 keer\n•	Laatste training met observator','1.	Kruispas  en wissel\n2.	Kruispas met hoge kniehef 15m en wissel\n3.	Triplings\n4.	Hielaanslag\n5.	Skippen \n6.	Skippen met actieve kniehef\n7.	Skippen met versnellen\n8.	Lopen met weerstand: \n2 lopers, 1 houdt de andere lopers bij heup of schouders vast.\n','2025-04-05','65 min rustige duurloop','Dynamische lunges','35 min rustige duurloop','Rustige duurloop met technische focus','Fase 3: Duur en snelheid verfijnen (17 mrt - 13 apr, 10 km)','','2025-01-13 19:53:02','2025-04-01 15:49:34','virgilsmit@gmail.com','dannyvdw@me.com'),(13,13,'2025-04-08','Fartlek: 5 min snel, 2 min rustig, 5x','Skipping, knieheffen','2025-04-12','Geen','Geen (wedstrijdherstel)','ZONDAG 13/4 HCR: 5 of 10 km wedstrijd (10 min in- en uitlopen)','Geen','Fase 3: Duur en snelheid verfijnen (17 mrt - 13 apr, 10 km)','13-apr-25','2025-01-13 19:53:02','2025-04-08 09:14:22',NULL,NULL),(14,14,'2025-04-15','Herstelloop: rustig tempo 3 x 10 min (Rustweek - geen intervaltraining)','Skipping, versnellingen','2025-04-19','Herstel: 4 x 10 minuten rustig tempo','Dynamische stretches, versnellingen','Dag 1: 40 min rustige duurloop, Dag 2: 30 min tempo duurloop','Afwisseling in looptechnieken, stabiliteitsoefeningen','Fase 4: 10 km Opbouw (14 apr - 26 jun)','','2025-01-13 19:53:02','2025-04-16 12:20:43','virgilsmit@gmail.com','hardlopen@virgilsmit.com'),(15,15,'2025-04-22','4 x 10 min hardlopen, 2 min rust','Afwisselend dynamische stretches, versnellingen, skipping','2025-04-26','Geen training ivm Koningsdag','Afwisselend knieheffen, skips, dynamische stretches','Afwisselend rustige duur en lange intervallen','Stretching, lichte versnellingen','Fase 4: 10 km Opbouw (14 apr - 26 jun)','','2025-01-13 19:53:02','2025-04-23 12:31:19','virgilsmit@gmail.com','hardlopen@virgilsmit.com'),(16,16,'2025-04-29','6 x 5 min hardlopen, 1 min rust','Huppelpas, skips','2025-05-03','35+35 minuten (opgesplitst)','Skipping, versnellingen','Dag 1: 50 min rustige duurloop, Dag 2: 35 min interval','Korte versnellingen, lichte oefeningen','Fase 4: 10 km Opbouw (14 apr - 26 jun)','','2025-01-13 19:53:02','2025-04-28 09:09:18','dannyvdw@me.com','virgilsmit@gmail.com'),(17,17,'2025-05-06','5 x 8 min hardlopen, 2 min rust','Dynamische stretches, knieheffen','2025-05-10','35+35 minuten (opgesplitst)','Huppelpas, skips','Dag 1: 45 min rustige duurloop, Dag 2: 30 min tempo','Dynamische stretching','Fase 4: 10 km Opbouw (14 apr - 26 jun)','','2025-01-13 19:53:02','2025-04-16 12:21:17',NULL,NULL),(18,18,'2025-05-13','3 x 15 min hardlopen, 3 min rust','Skipping, versnellingen (6x 50m)','2025-05-17','PVB Virgil -  AV PEC Zwolle -- Urksteeg 1\n8031 LL Zwolle','\n•	Triplings \n•	Dynamische ritmeoefening met focus op korte, snelle pasfrequentie. Arminzet controleren en romp recht houden.\n•	Skipping → versnelling: romp stilhouden, knieactie \n•	Versnellen vanuit skipping met nadruk op rompstabiliteit en actieve kniehef.\n•	– Skipping met hand op hoofd \n•	Focus op rompstilte en eigen balans zonder visuele controle van arminzet.\n•	– Skipping met één hand op hoofd, één op heup (met wissel) \n•	Activeert links-rechtsbewustzijn en corrigeert asymmetrische rotatie.\n•	– Skipping met hand op borst \n•	Voel je rompspanning bij het inzetten van knieën – romp stilhouden.\n•	– Skipping in tweetallen met hand op elkaars schouder \n•	Co-regulatie van rompstabiliteit, samenwerking vereist focus op balans.\n•	Weerstandsoefening in tweetallen \n•	Eén loper houdt vast bij de heupen, ander versnelt 15m – daarna wisselen.\n•	– Skipping met partnerdruk op schouders (staand achter) \n•	Rompstilte behouden ondanks achterwaartse druk tijdens skipping.\n•	– Skipping met tegenkracht op heup (partner achter) \n•	Core-activering tegen duwkracht, versnellen met controle.','Dag 1: 50 min rustige duurloop, Dag 2: 40 min interval','Afwisselen van tempo en techniek','Fase 4: 10 km Opbouw (14 apr - 26 jun)','','2025-01-13 19:53:02','2025-04-27 09:43:18','virgilsmit@gmail.com','virgilsmit@gmail.com'),(19,19,'2025-05-20','8 x 4 min hardlopen, 1 min rust','Laddersprongen, zijwaartse sprongen','2025-05-24','35+35 minuten (opgesplitst)','Dynamische lunges, knieheffen','Dag 1: 60 min rustige duurloop, Dag 2: 30 min hersteltempo','Rustige duurloop met technische focus','Fase 4: 10 km Opbouw (14 apr - 26 jun)','','2025-01-13 19:53:02','2025-04-16 12:21:30',NULL,NULL),(20,20,'2025-05-27','6 x 6 min hardlopen, 1 min rust','Knieheffen, skips','2025-05-31','60 min rustige duurloop (rustweek)','Skipping, versnellingen','Geen (rustweek)','Hersteltraining met lichte loopscholing','Fase 4: 10 km Opbouw (14 apr - 26 jun)','','2025-01-13 19:53:02','2025-04-16 12:21:33',NULL,NULL),(21,21,'2025-06-03','Fartlek: 5 min snel, 2 min rustig, 6x','Romprotaties, versnellingen','2025-06-07','35+35 minuten (opgesplitst)','Huppelpas, dynamische stretches','Dag 1: 70 min rustige duurloop, Dag 2: 40 min interval','Flexibiliteitsoefeningen','Fase 4: 10 km Opbouw (14 apr - 26 jun)','','2025-01-13 19:53:02','2025-04-16 12:21:46',NULL,NULL),(22,22,'2025-06-10','4 x 6 min hardlopen, 3 min rust (taper)','Skipping, knieheffen','2025-06-14','60 minuten rustige duurloop (taper)','Skipping, knieheffen','Dag 1: 75 min rustige duurloop, Dag 2: 35 min tempo','Afwisseling in looptechnieken, stabiliteitsoefeningen','Fase 4: 10 km Opbouw (14 apr - 26 jun)','','2025-01-13 19:53:02','2025-04-16 12:21:49',NULL,NULL),(23,23,'2025-06-17','2 x 3 min hardlopen, 2 min rust (wedstrijdvoorbereiding)','Huppelpas, dynamische stretches','2025-06-21','10 minuten loslopen (wedstrijdvoorbereiding)','Dynamische lunges, versnellingen','Dag 1: 80 min rustige duurloop, Dag 2: 40 min interval','Stretching, lichte versnellingen','Fase 4: 10 km Opbouw (14 apr - 26 jun)','','2025-01-13 19:53:02','2025-04-16 12:21:52',NULL,NULL),(24,24,'2025-06-24','Rustweek (geen intervaltraining)','Geen (wedstrijdherstel)','2025-06-28','Herstel: 30 minuten rustig tempo','Geen (wedstrijdherstel)','Geen (herstelweek)','Rust na zware training, lichte loopscholing','Fase 4: 10 km Opbouw (14 apr - 26 jun)','22-jun-25','2025-01-13 19:53:02','2025-04-16 12:21:54',NULL,NULL);
