  `session_id` varchar(255) NOT NULL,
  `post_status` varchar(255) NOT NULL,
  `post_type` varchar(255) NOT NULL,
  `post_id` bigint(20) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `site_alert_created` (`site_id`,`alert_id`,`created_on`),
